def first_even(values):
    for value in values:
        if value % 2 == 0:
            return value
    return None

def character_counts(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts

def largest(values):
    best = None
    for value in values:
        if best is None or value > best: best = value
    return best

def has_pair(values, target):
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] + values[j] == target: return True
    return False

def swapped(a, b):
    a, b = b, a
    return a, b
